  "task": "Summarize an approved note in one sentence",
  "configuration": {
    "model": "value supplied through PROJECT42_OPENAI_MODEL",
    "timeoutMilliseconds": 30000,
    "maxOutputTokens": 80
  },
  "dataPolicy": {
    "inputContainsSecrets": false,
    "printAuthorizationHeader": false,
