{
  "task": {
    "goal": "Summarize the approved maintenance note in one sentence",
    "approvedInput": "The service window begins at 02:00 UTC and requires operator approval."
  },
  "request": {
    "model": "MODEL_FROM_PROJECT42_OPENAI_MODEL",
    "instructions": "Return one concise sentence. Do not add facts.",
    "input": "The service window begins at 02:00 UTC and requires operator approval.",
    "max_output_tokens": 80
  },
  "response": {
    "id": "resp_synthetic_example",
    "status": "completed",
    "output": [
      { "type": "reasoning" },
      {
        "type": "message",
        "content": [
          {
            "type": "output_text",
            "text": "The 02:00 UTC service window requires operator approval."
          }
        ]
      }
    ]
  },
  "classification": {
    "kind": "text",
    "text": "The 02:00 UTC service window requires operator approval."
  }
}

const apiKey = process.env.OPENAI_API_KEY;
const model = process.env.PROJECT42_OPENAI_MODEL;
if (!apiKey || !model) {
  throw new Error('Missing OPENAI_API_KEY or PROJECT42_OPENAI_MODEL');
}

const allowed = new Set([
  'completed', 'incomplete', 'failed',
  'in_progress', 'queued', 'cancelled'
]);

const httpResponse = await fetch('https://api.openai.com/v1/responses', {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${apiKey}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    model,
    instructions: 'Return one concise sentence. Do not add facts.',
    input: 'Summarize this approved, non-secret note in one sentence.',
    max_output_tokens: 80
  }),
  signal: AbortSignal.timeout(30000)
});

const requestId = httpResponse.headers.get('x-request-id');
let body;
try {
  body = await httpResponse.json();
} catch {
  console.log(JSON.stringify({
    outcome: 'invalid-json',
    httpStatus: httpResponse.status,
    requestIdPresent: requestId !== null
  }));
  process.exitCode = 1;
  process.exit();
}

const diagnostic = {
  httpStatus: httpResponse.status,
  requestIdPresent: requestId !== null,
  responseIdPresent: typeof body?.id === 'string',
  responseStatus: allowed.has(body?.status) ? body.status : 'unknown'
};

if (!httpResponse.ok) {
  console.log(JSON.stringify({ ...diagnostic, outcome: 'http-failure' }));
  process.exitCode = 1;
} else if (!allowed.has(body?.status)) {
  console.log(JSON.stringify({ ...diagnostic, outcome: 'invalid-status' }));
  process.exitCode = 1;
} else if (body.status === 'failed') {
  console.log(JSON.stringify({ ...diagnostic, outcome: 'failed' }));
  process.exitCode = 1;
} else if (body.status === 'in_progress' || body.status === 'queued') {
  console.log(JSON.stringify({ ...diagnostic, outcome: 'pending' }));
} else if (body.status === 'cancelled') {
  console.log(JSON.stringify({ ...diagnostic, outcome: 'cancelled' }));
  process.exitCode = 1;
} else if (body.status === 'incomplete') {
  console.log(JSON.stringify({ ...diagnostic, outcome: 'incomplete' }));
  process.exitCode = 1;
} else if (!Array.isArray(body.output)) {
  console.log(JSON.stringify({ ...diagnostic, outcome: 'invalid-output' }));
  process.exitCode = 1;
} else {
  const blocks = body.output.flatMap((item) =>
    item?.type === 'message' && Array.isArray(item.content)
      ? item.content
      : []
  );
  const refused = blocks.some((part) => part?.type === 'refusal');
  const texts = blocks.filter((part) =>
    part?.type === 'output_text' && typeof part.text === 'string'
  );
  const outcome = refused ? 'refused' : texts.length ? 'candidate-text' : 'empty';
  console.log(JSON.stringify({
    ...diagnostic,
    outcome,
    outputTextBlockCount: texts.length
  }));
  if (outcome !== 'candidate-text') process.exitCode = 1;
}

