const allowed = new Set([
  'completed', 'incomplete', 'failed',
  'in_progress', 'queued', 'cancelled'
]);

export function classifyResponse(response) {
  if (!response || typeof response !== 'object') return { kind: 'invalid' };
  if (!Number.isInteger(response.httpStatus) ||
      response.httpStatus < 100 || response.httpStatus > 599) {
    return { kind: 'invalid' };
  }
  if (!allowed.has(response.status)) return { kind: 'invalid' };
  if (response.httpStatus < 200 || response.httpStatus > 299 ||
      response.status === 'failed') return { kind: 'failed' };
  if (response.status === 'in_progress' || response.status === 'queued') {
    return { kind: 'pending' };
  }
  if (response.status === 'cancelled') return { kind: 'cancelled' };
  if (!Array.isArray(response.output)) return { kind: 'invalid' };

  const texts = [];
  for (const item of response.output) {
    if (!item || item.type !== 'message') continue;
    if (!Array.isArray(item.content)) return { kind: 'invalid' };
    for (const part of item.content) {
      if (part?.type === 'output_text' && typeof part.text === 'string') {
        texts.push(part.text);
      }
    }
  }
  if (response.status === 'incomplete') {
    return texts.length
      ? { kind: 'text', text: texts.join(' ') }
      : { kind: 'incomplete' };
  }
  return texts.length
    ? { kind: 'text', text: texts.join(' ') }
    : { kind: 'empty' };
}
