import assert from 'node:assert/strict';
import { classifyResponse } from './learner.mjs';
import { cases } from './fixtures.mjs';

const allowed = new Set([
  'completed', 'incomplete', 'failed',
  'in_progress', 'queued', 'cancelled'
]);
const failures = [];

for (const item of cases) {
  const metadataErrors = [];
  if (!allowed.has(item.response?.status)) metadataErrors.push('status');
  if (!Number.isInteger(item.response?.httpStatus)) metadataErrors.push('httpStatus');
  if (Number.isInteger(item.response?.httpStatus) &&
      (item.response.httpStatus < 100 || item.response.httpStatus > 599)) {
    metadataErrors.push('httpStatusRange');
  }

  let actual;
  try {
    actual = classifyResponse(item.response);
  } catch (error) {
    actual = {
      kind: 'threw',
      name: typeof error?.name === 'string' ? error.name : 'Error'
    };
  }

  let resultError = null;
  try {
    assert.deepStrictEqual(actual, item.expected);
  } catch (error) {
    resultError = error;
  }

  if (metadataErrors.length === 0 && resultError === null) {
    console.log(`PASS ${item.name}: ${JSON.stringify(actual)}`);
  } else {
    failures.push(item.name);
    const metadata = metadataErrors.length
      ? `, fixture metadata errors ${JSON.stringify(metadataErrors)}`
      : '';
    console.log(
      `FAIL ${item.name}: expected ${JSON.stringify(item.expected)}, ` +
      `got ${JSON.stringify(actual)}${metadata}`
    );
  }
}

console.log(`${cases.length - failures.length}/${cases.length} cases passed`);
process.exitCode = failures.length ? 1 : 0;
